use atuin_common::utils::uuid_v7;
use uuid::Uuid;

/// A single execution of a script
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ScriptRun {
    /// Time-ordered (UUIDv7) id of this run
    pub id: Uuid,
    /// The script this run executed
    pub script_id: Uuid,
}

impl ScriptRun {
    /// Start a new run of `script_id`, with a fresh UUIDv7 id
    #[must_use]
    pub fn new(script_id: Uuid) -> Self {
        Self {
            id: uuid_v7(),
            script_id,
        }
    }
}

#[cfg(test)]
mod tests {
    use rstest::rstest;
    use uuid::Version;

    use super::*;

    #[rstest]
    fn new_assigns_v7_id() {
        let script_id = Uuid::new_v4();
        let run = ScriptRun::new(script_id);

        assert_eq!(run.script_id, script_id);
        assert_eq!(run.id.get_version(), Some(Version::SortRand));
    }
}
