#[cfg(test)]
mod tests {
    use std::thread::sleep;
    use std::time::Duration;

    use rstest::rstest;
    use uuid::Uuid;

    use super::ScriptRun;

    #[rstest]
    fn new_assigns_v7_id_and_keeps_script_id() {
        let script_id = Uuid::new_v4();
        let run = ScriptRun::new(script_id);

        assert_eq!(run.id.get_version_num(), 7);
        assert_eq!(run.script_id, script_id);
    }

    #[rstest]
    fn later_runs_sort_after_earlier_ones() {
        let script_id = Uuid::new_v4();
        let first = ScriptRun::new(script_id);
        // UUIDv7 is millisecond-granular, so make sure the clock has ticked
        sleep(Duration::from_millis(2));
        let second = ScriptRun::new(script_id);

        assert!(first.id < second.id);
    }
}
